// Directories implied by a task's typed `files[]` array. Mirrors filesToDirs in
// composites.ts — kept here to avoid a circular import (composites.ts imports
// BRANCH_ID_RE from tasks.ts). `filesJson` is the tasks.files JSON column.
function taskFileDirs(filesJson: string | null | undefined): Set<string> {
  const dirs = new Set<string>();
  if (!filesJson) return dirs;
  let files: unknown;
  try {
    files = JSON.parse(filesJson);
  } catch {
    return dirs;
  }
  if (!Array.isArray(files)) return dirs;
  for (const path of files) {
    if (typeof path !== 'string') continue;
    const slash = path.lastIndexOf('/');
    dirs.add(slash >= 0 ? path.slice(0, slash) : '');
  }
  return dirs;
}

export const BRANCH_ID_RE =
  /^(feat|fix|refactor|chore|docs|test|perf|build|ci|style|revert)\/[a-z0-9][a-z0-9-]{0,62}$/;

// Hard cap on tasks.spec_body. Architect should cite existing code/conventions
// rather than restate them; a spec longer than ~8k is usually a sign the task
// should be split via depends_on. Very long specs push SWE cold-start into the
// minutes range (issue #55: a 55k-char spec hung the session). Tunable via
// the TMB_SPEC_BODY_MAX_BYTES env var for downstream users with a different
// SWE token budget; defaults to 8000 chars.
export const SPEC_BODY_MAX_BYTES = (() => {
  const raw = process.env['TMB_SPEC_BODY_MAX_BYTES'];
  if (raw === undefined) return 8000;
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 8000;
})();

function validateBranchId(branchId: string): void {
  if (!BRANCH_ID_RE.test(branchId)) {
    throw new Error(
      `Invalid branch_id "${branchId}". Must match git-convention format: <type>/<slug> ` +
        `where <type> is one of feat|fix|refactor|chore|docs|test|perf|build|ci|style|revert ` +
        `and <slug> is lowercase alnum + hyphens (max 63 chars). Examples: feat/user-login, fix/auth-crash.`,
    );
  }
}

function isGitValidBranchName(name: string): boolean {
  return !/[\s~^:?*[\\]/.test(name) && !name.includes('..') && !name.startsWith('-') && !name.endsWith('/') && !name.endsWith('.lock');
}

function repoPolicyBranches(db: TrajectoryDB, repoValue: string | null): { names: Set<string>; target: string | null; repoPath: string | null } {
  const name = repoValue && repoValue.length > 0 ? repoValue : resolveSoleRepo(db)?.name ?? null;
  const names = new Set<string>();
  if (!name) return { names, target: null, repoPath: null };
  const row = db.get<{ path: string; target_branch: string | null; protected_branches: string | null }>(
    `SELECT path, target_branch, protected_branches FROM repos WHERE name = ?`,
    [name],
  );
  if (!row) return { names, target: null, repoPath: null };
  if (row.target_branch) names.add(row.target_branch);
  try {
    const parsed: unknown = JSON.parse(row.protected_branches ?? '[]');
    if (Array.isArray(parsed)) for (const b of parsed) if (typeof b === 'string') names.add(b);
  } catch {
    // malformed protected_branches contributes no names
  }
  return { names, target: row.target_branch || null, repoPath: repoRowPath(db, row.path) };
}

function validateParentBranchId(branchId: string, db: TrajectoryDB, repoValue: string | null): void {
  if (BRANCH_ID_RE.test(branchId)) return;
  const { names, target, repoPath } = repoPolicyBranches(db, repoValue);
  if (isGitValidBranchName(branchId) && (names.has(branchId) || (repoPath !== null && branchRefExists(repoPath, branchId)))) return;
  throw new Error(
    `Invalid branch_id "${branchId}". Must be the repo's target branch (${target ?? 'unset'}), a protected branch, ` +
      `an existing branch, or git-convention format: <type>/<slug> where <type> is one of ` +
      `feat|fix|refactor|chore|docs|test|perf|build|ci|style|revert ` +
      `and <slug> is lowercase alnum + hyphens (max 63 chars). Examples: feat/user-login, fix/auth-crash.`,
  );
}

// Typed Rails (#673): validate the per-task files[]/verification[] fields at the
// MCP boundary. Flat schema (no oneOf/allOf/anyOf): each field, when present,
// must be a non-empty array of non-empty strings, and effort one of
// low|medium|high. Throws a named error so the model can retry with a
// corrected shape. Returns the normalized arrays (omitted/undefined → empty
// array, which disables the corresponding hook) and the effort (undefined when
// omitted: the caller computes it with computeEffort).
function validateTypedRailsFields(t: TaskInput): { files: string[]; verification: string[]; effort: Effort | undefined } {
  const checkStringArray = (value: unknown, field: 'files' | 'verification'): string[] => {
    if (value === undefined || value === null) return [];
    if (!Array.isArray(value)) {
      throw new Error(
        `typed_field_violation: task branch_id='${t.branch_id}' — '${field}' must be an array of strings, got ${typeof value}.`,
      );
    }
    if (value.length === 0) {
      throw new Error(
        `typed_field_violation: task branch_id='${t.branch_id}' — '${field}' must be a non-empty array when provided (omit the field entirely ${field === 'files' ? 'to declare no expected scope: no edit-time notes, and every changed path is an extra at close' : 'to disable the verification gate'}).`,
      );
    }
    for (const el of value) {
      if (typeof el !== 'string' || el.trim().length === 0) {
        throw new Error(
          `typed_field_violation: task branch_id='${t.branch_id}' — every '${field}' entry must be a non-empty string.`,
        );
      }
    }
    return value as string[];
  };
  if (t.effort !== undefined && t.effort !== null && !isEffort(t.effort)) {
    throw new Error(
      `typed_field_violation: task branch_id='${t.branch_id}' — 'effort' must be one of ${EFFORT_LEVELS.join(', ')}, got ${JSON.stringify(t.effort)}.`,
    );
  }
  return {
    files: checkStringArray(t.files, 'files'),
    verification: checkStringArray(t.verification, 'verification'),
    effort: isEffort(t.effort) ? t.effort : undefined,
  };
}

// Allowed target statuses for swe. SWE may only set running, completed, or
// failed — pre-execution states (pending, escalated) are bro-managed; 'closed'
// is bro's atomic-close transition; 'needs_validation' is not a valid SWE
// terminal state. Additionally, closed and escalated are terminal for SWE —
// a closed task cannot be touched by SWE. See #114, #343.
const SWE_ALLOWED_TARGET_STATUSES = new Set(['running', 'completed', 'failed']);

// States that SWE may not transition OUT OF (terminal for SWE).
const SWE_LOCKED_SOURCE_STATES = new Set(['closed', 'escalated']);

type BranchAutocreatedAudit = {
  branchId: string;
  startPoint: string;
  repoPath: string;
};

function ensureBranchInRepo(
  branchId: string,
  repoPath: string,
  parentBranchId: string | null,
): BranchAutocreatedAudit | null {
  const existsResult = spawnSync('git', ['-C', repoPath, 'rev-parse', '--verify', branchId], {
    encoding: 'utf8',
    timeout: SUBPROCESS_TIMEOUT_MS,
  });
  if (existsResult.status === 0) return null;

  const stderr = (existsResult.stderr ?? '') as string;
  if (stderr.includes('not a git repository') || stderr.includes('cannot change to')) {
    serverLog({
      level: 'warn',
      msg: `[task_create_batch] repo '${repoPath}' is not a resolvable git repository; skipping branch-existence check for '${branchId}'.`,
    });
    return null;
  }

  let startPoint = 'HEAD';
  if (parentBranchId) {
    const parentResult = spawnSync(
      'git',
      ['-C', repoPath, 'rev-parse', '--verify', parentBranchId],
      { encoding: 'utf8', timeout: SUBPROCESS_TIMEOUT_MS },
    );
    if (parentResult.status === 0) startPoint = parentBranchId;
  }

  const createResult = spawnSync('git', ['-C', repoPath, 'branch', branchId, startPoint], {
    encoding: 'utf8',
    timeout: SUBPROCESS_TIMEOUT_MS,
  });
  if (createResult.status !== 0) {
    throw new Error(
      `task_create_batch: failed to auto-create branch '${branchId}' from '${startPoint}' in repo '${repoPath}': ` +
        ((createResult.stderr ?? '') as string).trim(),
    );
  }

  return { branchId, startPoint, repoPath };
}

const VALID_STATUSES = new Set([
  'pending',
  'running',
  'needs_validation',
  'completed',
  'closed',
  'failed',
  'escalated',
]);

// Allowed status transitions for bro (#278). Without this, bro could move any
// status to any status — e.g. pending→closed (skipping verification) or
// closed→completed (re-satisfying a downstream gate by fiat). Keys not present
// reject every outbound move; a same-status no-op is always allowed.
//   - Into 'completed' only from a work state (running / needs_validation) —
//     bro can't fabricate completion from pending or a terminal state.
//   - The only path from a verified work state (needs_validation / completed)
//     into 'closed' is bro_atomic_close, so task_update_status must not offer
//     those edges (else bro could close a task without the atomic close's
//     side effects).
//   - 'closed'→'escalated' hands a closed task back to the Human; rework
//     after a failed review goes through task_reopen (closed → running).
const BRO_TRANSITIONS: Record<string, Set<string>> = {
  pending: new Set(['running', 'failed', 'escalated']),
  running: new Set(['pending', 'needs_validation', 'completed', 'failed', 'escalated']),
  needs_validation: new Set(['running', 'completed', 'failed', 'escalated']),
  completed: new Set(['needs_validation', 'failed', 'escalated']),
  failed: new Set(['pending', 'running', 'escalated', 'closed']),
  escalated: new Set(['pending', 'running', 'failed', 'closed']),
  closed: new Set(['escalated']),
};

function ok(data: unknown): CallToolResult {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

function err(message: string): CallToolResult {
  return {
    content: [{ type: 'text', text: JSON.stringify({ error: message }) }],
    isError: true,
  };
}

function requireArg(args: Record<string, unknown>, name: string): unknown {
  if (args[name] === undefined || args[name] === null) {
    throw new Error(`Missing required arg: ${name}`);
  }
  return args[name];
}

function wrapHandler(fn: (args: Record<string, unknown>) => Promise<CallToolResult>): Fn {
  return async (args) => {
    try {
      return await fn(args);
    } catch (e) {
      return err((e as Error).message);
    }
  };
}

export type SpecShapeWaiverSource = 'task_create_batch' | 'task_provision';

// One spec_shape_gate_waived row per task, in the shape require-task-spec.sh
// reads to open the SWE spawn gate (from_node 'bro', $.task_id, $.gate, $.reason).
export function insertSpecShapeWaiver(
  db: TrajectoryDB,
  task: { issue_id: number | string; branch_id: string; task_id: number },
  reason: string,
  source: SpecShapeWaiverSource,
  createdAt: string,
): void {
  insertAudit(db, {
    issue_id: task.issue_id,
    branch_id: task.branch_id,
    from_node: 'bro',
    event_type: 'spec_shape_gate_waived',
    summary: reason.slice(0, 200),
    content_json: JSON.stringify({ task_id: task.task_id, gate: 'spec_shape', reason, waived_by: 'bro', source }),
    created_at: createdAt,
  });
}

