import path from 'node:path';
import { mkdirSync, readFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  ListToolsRequestSchema,
  CallToolRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import { toolDefinitions, toolHandlers, registerTools } from './tools/index.js';
import { TrajectoryDB, nowISO, resolveDbPath } from './db.js';
import { serverLog, serverLogSync } from './logger.js';
import { startBackfill } from './embeddings/backfill.js';
import { embed } from './embeddings/model.js';
import { reconcileAtStartup } from './tools/cheatcode-reconcile.js';
import { recordEmbeddingTransitions } from './embeddings/health.js';
import { WorldModelGraph, GraphHolder } from './graph.js';
import { createShutdown, installShutdownHandlers } from './shutdown.js';
import { startStartupCatchup } from './startup-catchup.js';

const dbPath = resolveDbPath();
if (dbPath !== ':memory:') {
  mkdirSync(path.dirname(dbPath), { recursive: true });
}

const db = new TrajectoryDB(dbPath, undefined, { migrate: true });

function readPackageVersion(): string {
  try {
    const here = path.dirname(new URL(import.meta.url).pathname);
    const pkgPath = path.join(here, '..', 'package.json');
    const pkg = JSON.parse(readFileSync(pkgPath, 'utf8')) as { version?: string };
    return typeof pkg.version === 'string' ? pkg.version : '0.0.0';
  } catch {
    return '0.0.0';
  }
}

const packageVersion = readPackageVersion();

// The world model shares the trajectory DB handle (GH 1632).
const graphHolder = GraphHolder.fixed(new WorldModelGraph(db));

const server = new Server(
  { name: 'trajectory-server', version: packageVersion },
  { capabilities: { tools: {} } },
);

registerTools(server, db, dbPath, graphHolder);

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: toolDefinitions,
}));

// L5 trajectory capture. Requires both TMB_DEBUG_TRAJECTORY=1 (opt-in switch)
// AND TMB_EVAL_MODE=1 — the latter is what loads schema-eval.sql, which is
// where the `debug_trajectory` table is defined. Without eval mode the
// INSERT would target a missing table and silently no-op.
// Session ID is per-server-spawn — covers a single `claude -p` invocation.
const debugTrajectoryEnabled =
  process.env['TMB_DEBUG_TRAJECTORY'] === '1' && process.env['TMB_EVAL_MODE'] === '1';
const debugSessionId = crypto.randomUUID();
let debugStepCounter = 0;

function maybeRecordTrajectory(
  toolName: string,
  args: unknown,
  result: { content?: ReadonlyArray<unknown>; isError?: boolean },
): void {
  if (!debugTrajectoryEnabled) return;
  try {
    const agentName = (args as { agent?: string } | undefined)?.agent ?? null;
    const argsJson = JSON.stringify(args ?? {}).slice(0, 4000);
    const firstContent = result.content?.[0] as { text?: unknown } | undefined;
    const resultText =
      firstContent && typeof firstContent.text === 'string' ? firstContent.text : '';
    const resultJson = JSON.stringify({ text: resultText.slice(0, 4000) });
    db.run(
      `INSERT INTO debug_trajectory
       (session_id, step_n, kind, agent, tool_or_mcp_name, args_json, result_json, is_error, created_at)
       VALUES (?, ?, 'mcp_call', ?, ?, ?, ?, ?, ?)`,
      [
        debugSessionId,
        ++debugStepCounter,
        agentName,
        toolName,
        argsJson,
        resultJson,
        result.isError ? 1 : 0,
        nowISO(),
      ],
    );
  } catch {
    // Trajectory capture must never break the actual tool call.
  }
}

const shutdown = createShutdown({
  closeDb: () => db.close(),
  log: (signal) => serverLogSync({ kind: 'shutdown', signal, pid: process.pid }),
  exit: (code) => process.exit(code),
  pid: process.pid,
});

process.on('uncaughtException', (err: Error) => {
  serverLogSync({ kind: 'uncaughtException', error_message: err.message, stack: err.stack, pid: process.pid });
  process.stderr.write(`uncaughtException: ${err.message}\n${err.stack ?? ''}\n`);
  process.exit(1);
});

process.on('unhandledRejection', (reason: unknown) => {
  const msg = reason instanceof Error ? reason.message : String(reason);
  const stack = reason instanceof Error ? reason.stack : undefined;
  serverLogSync({ kind: 'unhandledRejection', error_message: msg, stack, pid: process.pid });
  process.stderr.write(`unhandledRejection: ${msg}\n`);
  process.exit(1);
});

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;
  const handler = toolHandlers[name];
  if (!handler) {
    throw new Error(`Unknown tool: ${name}`);
  }
  const start = performance.now();
  const agent = (args as Record<string, unknown> | undefined)?.agent ?? null;
  serverLog({ kind: 'tool_entry', tool: name, agent });

  if (name === 'task_create_batch') {
    const typedArgs = args as Record<string, unknown> | undefined;
    const tasks = (typedArgs?.['tasks'] ?? []) as Array<{ spec_body?: string }>;
    const total_bytes = JSON.stringify(args ?? {}).length;
    const max_spec_bytes = tasks.length > 0
      ? Math.max(...tasks.map((t) => (t.spec_body ?? '').length))
      : 0;
    const n_tasks = tasks.length;
    serverLog({ kind: 'tool_size', tool: 'task_create_batch', total_bytes, max_spec_bytes, n_tasks, agent });
    if (max_spec_bytes > 8192) {
      serverLog({
        kind: 'oversize_warning',
        tool: 'task_create_batch',
        total_bytes,
        max_spec_bytes,
        n_tasks,
        agent,
        threshold: 8192,
        upstream_ref: 'anthropics/claude-code#36319',
      });
    }
  }

  let result: Awaited<ReturnType<typeof handler>>;
  try {
    result = await handler(args ?? {});
  } catch (err) {
    const duration_ms = Math.round(performance.now() - start);
    serverLog({
      kind: 'tool_exit',
      tool: name,
      agent,
      is_error: true,
      error_message: err instanceof Error ? err.message : String(err),
      duration_ms,
    });
    throw err;
  }
  const duration_ms = Math.round(performance.now() - start);
  serverLog({
    kind: 'tool_exit',
    tool: name,
    agent,
    is_error: result.isError ?? false,
    duration_ms,
  });
  maybeRecordTrajectory(name, args, result);
  return result;
});

installShutdownHandlers(shutdown, process, process.stdin);

const transport = new StdioServerTransport();
await server.connect(transport);
serverLog({
  kind: 'startup',
  pid: process.pid,
  version: packageVersion,
  db_path: dbPath,
  legacy_db_no_plugin_meta: db.legacyNoPluginMeta,
});
startStartupCatchup(dbPath);

process.stderr.write(`server started (db: ${dbPath})\n`);
if (db.legacyNoPluginMeta) {
  process.stderr.write(
    'WARNING: trajectory DB had tables but no plugin_meta row (pre-stamp legacy); adopted forward and stamped. Verify the upgrade.\n',
  );
}

void reconcileAtStartup(db);
recordEmbeddingTransitions(db);
embed('warmup').catch(() => {});
startBackfill(db).catch((e) => console.error('[embeddings] startBackfill error:', e));
